from pathlib import Path
import json,html
R=Path(__file__).resolve().parent.parent;S=json.loads((R/'scenes.json').read_text());(R/'boards').mkdir(exist_ok=True)
style='''*{box-sizing:border-box}body{margin:0;background:#EDE9E3;color:#241E1A;font-family:Inter,Arial,sans-serif}h1,h2{font-family:"Playfair Display",Georgia,serif;font-weight:400;margin:0}a{color:#713F35;text-decoration:none}header{padding:28px 36px;background:#FAF7F2;border-bottom:1px solid #CDBFB0;display:flex;justify-content:space-between;gap:24px;align-items:center}header h1{font-size:31px}header p{margin:8px 0 0;font-size:12px;color:#65574C;max-width:800px;line-height:1.6}.count{font-size:11px;letter-spacing:.12em;white-space:nowrap;color:#713F35}main{padding:28px 30px 36px}.devices{display:grid;grid-template-columns:1440fr 834fr 390fr;gap:22px;align-items:start}figure{margin:0;min-width:0}figcaption{display:flex;justify-content:space-between;font-size:12px;margin:0 0 12px;gap:10px}figcaption small{font-size:10px;color:#65574C}img{display:block;width:100%;height:auto;background:#FAF7F2;box-shadow:0 4px 22px #241e1a0c;border:1px solid #D8CDC2}footer{padding:17px 30px 24px;font-size:10px;color:#65574C;display:flex;justify-content:space-between;border-top:1px solid #D4C9BD;line-height:1.6}nav{display:flex;gap:18px;font-size:11px}button{font:inherit}'''
fonts='<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=Playfair+Display:wght@400;500&display=swap">'
for n,s in enumerate(S,1):
 figures=''
 for d,label,size in [('desktop','Desktop','1440 × 1000'),('tablet','Tablet','834 × 1112'),('mobile','Mobile','390 × 844')]:
  f=s['id']+'-'+d+'.png';figures+=f'<figure><figcaption><strong>{label}</strong><small>{size} viewport</small></figcaption><a href="../images/{f}"><img alt="{html.escape(s["title"])} · {d}" src="../images/{f}"></a></figure>'
 prev=S[max(0,n-2)]['id']+'.html';nxt=S[min(14,n)]['id']+'.html'
 body=f'<header><div><div class="count">THREADLINE / SENSE · VISUAL TARGET V1 · {n:02d} / 15</div><h1>{s["title"]}</h1><p>{s["description"]}</p></div><nav><a href="{prev}">← Previous</a><a href="../index.html">Storybook</a><a href="{nxt}">Next →</a></nav></header><main><div class="devices">{figures}</div></main><footer><span>Full-page responsive mockups. Fictional product/customer/order data. Original generated photography.</span><span>Shared checkout & identity · No live transactions · 22 October 2026</span></footer>'
 (R/'boards'/f'{s["id"]}.html').write_text(f'<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{s["title"]} · Threadline responsive board</title>{fonts}<style>{style}</style>{body}</html>')
# Responsive storybook, with real PNGs rather than transient server-rendered iframes.
galleryCSS=style+'''header{position:sticky;top:0;z-index:2}header h1{font-size:29px}.layout{display:grid;grid-template-columns:260px minmax(0,1fr);min-height:100vh}.toc{padding:24px 18px;background:#FAF7F2;border-right:1px solid #D8CDC2;position:sticky;top:110px;height:calc(100vh - 110px);overflow:auto}.toc a{display:block;padding:11px 12px;font-size:12px;line-height:1.5;border-radius:4px;color:#65574C}.toc a.active{background:#E9DFD3;color:#713F35}.toc b{font-weight:500;margin-right:6px}.viewer{min-width:0;padding:28px}.scene{display:none}.scene.active{display:block}.scene h2{font-size:31px;margin-bottom:9px}.scene>p{font-size:12px;color:#65574C;margin:0 0 23px;line-height:1.6}.scene .devices{gap:17px}.tools{display:flex;gap:18px;flex-wrap:wrap;margin:22px 0;font-size:11px}.tools a{border:1px solid #B7A998;padding:9px 12px;background:#FAF7F2;border-radius:4px}.note{font-size:11px;line-height:1.8;color:#65574C;background:#FAF7F2;padding:15px 18px;margin:0 0 23px;border:1px solid #D8CDC2}.mobile-nav{display:none}.device-picker{display:flex;gap:8px;margin-bottom:24px}.device-picker button{border:1px solid #B7A998;border-radius:4px;padding:8px 12px;background:#FAF7F2;color:#65574C;font-size:11px;cursor:pointer}.device-picker button.active{background:#713F35;border-color:#713F35;color:white}body[data-device=desktop] .devices,body[data-device=tablet] .devices,body[data-device=mobile] .devices{display:block}body[data-device=desktop] figure:not([data-device=desktop]),body[data-device=tablet] figure:not([data-device=tablet]),body[data-device=mobile] figure:not([data-device=mobile]){display:none}body[data-device=mobile] figure{max-width:390px;margin:auto}body[data-device=tablet] figure{max-width:834px;margin:auto}@media(max-width:900px){header{padding:20px}header h1{font-size:25px}.layout{display:block}.toc{display:none}.mobile-nav{display:block;background:#FAF7F2;padding:15px 20px;border-bottom:1px solid #D8CDC2}.mobile-nav select{width:100%;padding:10px;font:13px Inter,Arial;border:1px solid #B7A998;background:white;color:#241E1A}.viewer{padding:20px}.count{white-space:normal}header .downloads{display:none}.scene .devices{grid-template-columns:1fr;gap:32px}.scene figure{max-width:100%}.note{font-size:10px}}'''
nav=''.join(f'<a href="#{s["id"]}" data-target="{s["id"]}" class="{"active" if i==0 else ""}"><b>{i+1:02d}</b>{s["title"]}</a>'for i,s in enumerate(S))
scenes=''
for i,s in enumerate(S):
 figs=''
 for d,label,size in [('desktop','Desktop','1440 × 1000'),('tablet','Tablet','834 × 1112'),('mobile','Mobile','390 × 844')]:
  f=s['id']+'-'+d+'.png';figs+=f'<figure data-device="{d}"><figcaption><strong>{label}</strong><small>{size} viewport</small></figcaption><a href="images/{f}"><img loading="lazy" alt="{html.escape(s["title"])} · {label}" src="images/{f}"></a></figure>'
 scenes+=f'<section class="scene {"active" if i==0 else ""}" id="{s["id"]}"><h2>{s["title"]}</h2><p>{s["description"]}</p><div class="tools"><a href="boards/{s["id"]}.html">Three-device board</a><a href="boards/{s["id"]}.png">Board PNG</a><a href="source/{s["id"]}.html">Responsive visual source</a></div><div class="devices">{figs}</div></section>'
script='''const sections=[...document.querySelectorAll('.scene')];function show(id){if(!sections.some(s=>s.id===id))id=sections[0].id;sections.forEach(s=>s.classList.toggle('active',s.id===id));document.querySelectorAll('.toc a').forEach(a=>a.classList.toggle('active',a.dataset.target===id));document.querySelector('.mobile-nav select').value=id;}window.addEventListener('hashchange',()=>show(location.hash.slice(1)));show(location.hash.slice(1));document.querySelectorAll('.device-picker button').forEach(b=>b.addEventListener('click',()=>{document.body.dataset.device=b.dataset.device;document.querySelectorAll('.device-picker button').forEach(x=>x.classList.toggle('active',x===b));}));document.querySelector('.mobile-nav select').addEventListener('change',e=>location.hash=e.target.value);document.addEventListener('keydown',e=>{if(e.target.tagName==='SELECT'||e.target.tagName==='INPUT')return;let i=sections.findIndex(s=>s.classList.contains('active'));if(e.key==='ArrowRight')location.hash=sections[Math.min(sections.length-1,i+1)].id;if(e.key==='ArrowLeft')location.hash=sections[Math.max(0,i-1)].id;});'''
htmlpage=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Threadline · 45-image visual storybook</title>{fonts}<style>{galleryCSS}</style><body data-device="all"><header><div><div class="count">LETBUYY STOREFRONTS / THREADLINE</div><h1>A wardrobe, thoughtfully connected.</h1><p>15 page states · Desktop, tablet and mobile · 45 full-size PNGs</p></div><nav class="downloads"><a href="Threadline-45-mockups.zip">Download 45 PNGs ↓</a><a href="README.md">Design handoff</a></nav></header><div class="mobile-nav"><select aria-label="Choose a storybook scene">{''.join(f'<option value="{s["id"]}">{i+1:02d} · {s["title"]}</option>'for i,s in enumerate(S))}</select></div><div class="layout"><nav class="toc" aria-label="Scenes">{nav}</nav><main class="viewer"><div class="note">Visual implementation reference v1. Prices, measurements, account details and orders are fictional fixtures. Checkout and identity remain shared LetBuyy systems. These images do not represent installed or published themes.</div><div class="device-picker" aria-label="Choose device view"><button class="active" data-device="all">All three</button><button data-device="desktop">Desktop</button><button data-device="tablet">Tablet</button><button data-device="mobile">Mobile</button></div>{scenes}</main></div><script>{script}</script></body></html>'''
(R/'index.html').write_text(htmlpage)
